package com.adhamelgendy.nixura.auth

import android.content.Context
import android.content.pm.PackageManager
import android.content.pm.Signature
import android.os.Build
import com.adhamelgendy.nixura.data.auth.FirebaseConfig
import java.security.MessageDigest

/**
 * Firebase settings for this build. The key and client id are generated by the google-services plugin from
 * `androidApp/google-services.json`. The package + signing SHA-1 headers let Google accept the key when it is
 * restricted to this Android app.
 */
object AndroidFirebaseConfig {

    fun of(context: Context): FirebaseConfig = FirebaseConfig(
        apiKey = string(context, "google_api_key"),
        platformHeaders = buildMap {
            put("X-Android-Package", context.packageName)
            signingSha1(context)?.let { put("X-Android-Cert", it) }
        },
    )

    /** The Firebase project's web OAuth client, used by Google sign-in. Empty if `google-services.json` has none. */
    fun webClientId(context: Context): String = string(context, "default_web_client_id")

    private fun string(context: Context, name: String): String {
        val id = context.resources.getIdentifier(name, "string", context.packageName)
        return if (id == 0) "" else context.getString(id)
    }

    @Suppress("DEPRECATION")
    private fun signingSha1(context: Context): String? = runCatching {
        val pm = context.packageManager
        val signature: Signature? = if (Build.VERSION.SDK_INT >= Build.VERSION_CODES.P) {
            pm.getPackageInfo(context.packageName, PackageManager.GET_SIGNING_CERTIFICATES).signingInfo?.apkContentsSigners?.firstOrNull()
        } else {
            pm.getPackageInfo(context.packageName, PackageManager.GET_SIGNATURES).signatures?.firstOrNull()
        }
        signature?.let { sig -> MessageDigest.getInstance("SHA-1").digest(sig.toByteArray()).joinToString("") { "%02X".format(it) } }
    }.getOrNull()
}
